<script setup lang="ts">
const props=defineProps<{documentId:number;kind:'asn'|'dn';current:string}>()
const {t}=useI18n(),flow=ref<{steps:{key:string;state:string}[]}|null>(null)
let generation=0
watch(()=>[props.kind,props.documentId],async()=>{const seq=++generation;flow.value=null;if(!useStaffStore().hasPermission(props.kind+'_read'))return;const result=await httpRequest<any>('/api/warehouse/'+props.kind+'/'+props.documentId+(props.kind==='asn'?'/flow':'/shipping-flow'));if(seq===generation)flow.value=result},{immediate:true});onBeforeUnmount(()=>generation++)
</script>
<template><div v-if="flow" class="w-compact-flow"><strong>{{kind.toUpperCase()}}-{{documentId}} {{t('operations.ui.progress')}}</strong><ol><li v-for="(step,index) in flow.steps" :key="step.key"><span v-if="step.key!==current" class="w-flow-dot" :class="step.state" :title="t((kind==='asn'?'asn.flow.steps.':'shipping.steps.')+step.key)" /><span v-if="step.key===current" class="w-flow-label" aria-current="step">{{t((kind==='asn'?'asn.flow.steps.':'shipping.steps.')+step.key)}} · {{t('operations.ui.this-page')}}</span><span v-if="index<flow.steps.length-1" class="w-flow-line" :class="{'is-done':step.state==='done'}" /></li></ol><NuxtLink class="w-flow-link" :to="'/'+kind+'/detail/'+documentId">{{t('operations.ui.full-flow')}} →</NuxtLink></div></template>
<style scoped>
.w-compact-flow{display:flex;align-items:center;flex-wrap:wrap;gap:12px 24px;padding:12px 20px;border:1px solid var(--w-border);border-radius:10px;background:var(--w-surface);font-size:13px;line-height:20px}.w-compact-flow strong{font-weight:500;color:var(--w-text-2)}.w-compact-flow ol{display:flex;align-items:center;flex:1 1 360px;min-width:0;list-style:none;margin:0;padding:0}.w-compact-flow li{display:flex;align-items:center;flex:1}.w-compact-flow li:last-child{flex:0}.w-flow-dot{width:8px;height:8px;box-sizing:border-box;border-radius:50%;border:2px solid var(--w-border-strong);flex:none}.w-flow-dot.done{background:var(--w-ok-dot);border:0}.w-flow-label{display:inline-flex;align-items:center;flex:none;height:24px;padding:0 10px;border-radius:999px;box-shadow:inset 0 0 0 1px var(--w-brand-400);background:var(--w-surface);font-size:12px;line-height:18px;color:var(--w-sel-text);font-weight:600;white-space:nowrap}.w-flow-line{height:2px;flex:1;min-width:12px;background:var(--w-border)}.w-flow-line.is-done{background:var(--w-ok-dot)}.w-flow-link{color:var(--w-link);font-weight:500;text-decoration:none}
</style>
